// pyFloat.mjs
// Faithful reimplementation of CPython's float() string parsing and
// repr()/str() float formatting, so numeric output matches Python exactly.

// Error thrown when a string cannot be converted to a float, mirroring
// Python's `ValueError: could not convert string to float: ...`.
export class FloatParseError extends Error {
  constructor(text) {
    super(`could not convert string to float: ${text}`);
    this.name = 'FloatParseError';
  }
}

// CPython digit-part: digits optionally separated by single underscores
// (PEP 515), e.g. "1_000". Underscores must sit between two digits.
const DIGIT_PART = '\\d(?:_?\\d)*';
const FLOAT_RE = new RegExp(
  `^[+-]?(?:${DIGIT_PART}(?:\\.(?:${DIGIT_PART})?)?|\\.${DIGIT_PART})` +
    `(?:[eE][+-]?${DIGIT_PART})?$`
);
const INF_NAN_RE = /^[+-]?(inf(inity)?|nan)$/i;

// Parse a string the way Python's built-in float() does.
// Throws FloatParseError on failure (argparse turns this into
// "invalid float value" errors).
export function parsePythonFloat(text) {
  const s = text.trim();
  if (INF_NAN_RE.test(s)) {
    const lower = s.toLowerCase();
    const negative = lower.startsWith('-');
    if (lower.includes('nan')) return NaN;
    return negative ? -Infinity : Infinity;
  }
  if (!FLOAT_RE.test(s)) {
    throw new FloatParseError(text);
  }
  return Number(s.replace(/_/g, ''));
}

// Format a finite double exactly like CPython's repr(float):
// shortest round-trip digits, fixed notation when -4 < decpt <= 16,
// scientific notation otherwise (exponent always signed, >= 2 digits).
export function pythonFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const negative = x < 0;
  const mag = Math.abs(x);

  // toExponential() without an argument yields the shortest string of
  // digits that round-trips to the same double — the same digit sequence
  // CPython's dtoa(mode 0) produces.
  const expForm = mag.toExponential(); // e.g. "1.23456e+2"
  const eIndex = expForm.indexOf('e');
  const mantissa = expForm.slice(0, eIndex);
  const exp10 = parseInt(expForm.slice(eIndex + 1), 10);
  const digits = mantissa.replace('.', '');
  // Value = 0.<digits> * 10^decpt  (dtoa convention)
  const decpt = exp10 + 1;

  let body;
  if (decpt <= -4 || decpt > 16) {
    // Scientific notation: d[.ddd]e±XX
    body = digits[0];
    if (digits.length > 1) body += '.' + digits.slice(1);
    const e = decpt - 1;
    body +=
      'e' + (e < 0 ? '-' : '+') + String(Math.abs(e)).padStart(2, '0');
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + body : body;
}

// str(float): identical to repr(float) in Python 3.
export function pythonFloatStr(x) {
  return pythonFloatRepr(x);
}

