// pyRepr.mjs
// Reimplementations of Python's repr() for str and bytes objects, used to
// reproduce Python's print() output byte-for-byte.

// repr() of a Python str: single quotes preferred, double quotes when the
// string contains a single quote but no double quote; standard escapes.
export function pythonStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// repr() of a Python bytes object built from a JS string (UTF-8 encoded),
// e.g. b'-3.14159' — this is what print(bytes) shows in Python.
export function pythonBytesRepr(s) {
  const bytes = new TextEncoder().encode(s);
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quoteByte = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quote = String.fromCharCode(quoteByte);
  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) out += '\\\\';
    else if (b === quoteByte) out += '\\' + quote;
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b >= 0x20 && b < 0x7f) out += String.fromCharCode(b);
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + quote;
}

