// canonicalJson.mjs
// Reimplementation of canonicaljson.encode_canonical_json behavior:
// - floats use Python repr() formatting (shortest round-trip)
// - object keys sorted, separators are "," and ":" (no whitespace)
// - non-finite floats are rejected (allow_nan=False)
// The encoder is hand-written; JSON.stringify is intentionally not used.

import { pythonFloatRepr } from './pyFloat.mjs';

// Mirrors Python's ValueError raised by json.encoder for inf/nan.
export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

function encodeFloat(x) {
  if (Number.isNaN(x)) {
    throw new ValueError('Out of range float values are not JSON compliant: nan');
  }
  if (!Number.isFinite(x)) {
    throw new ValueError(
      'Out of range float values are not JSON compliant: ' +
        (x > 0 ? 'inf' : '-inf')
    );
  }
  return pythonFloatRepr(x);
}

// JSON string escaping matching Python's json.dumps with ensure_ascii=False.
function encodeString(s) {
  let out = '"';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (ch === '\b') out += '\\b';
    else if (ch === '\f') out += '\\f';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20) out += '\\u' + code.toString(16).padStart(4, '0');
    else out += ch;
  }
  return out + '"';
}

function encode(value) {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number') return encodeFloat(value);
  if (typeof value === 'string') return encodeString(value);
  if (Array.isArray(value)) {
    return '[' + value.map(encode).join(',') + ']';
  }
  if (typeof value === 'object') {
    const keys = Object.keys(value).sort();
    const parts = keys.map((k) => encodeString(k) + ':' + encode(value[k]));
    return '{' + parts.join(',') + '}';
  }
  throw new TypeError(`Object of type ${typeof value} is not JSON serializable`);
}

// Equivalent of canonicaljson.encode_canonical_json, returning the JSON
// text (the Python function returns this same text encoded as UTF-8 bytes).
export function encodeCanonicalJson(value) {
  return encode(value);
}

